from pathlib import Path
import json,re
root=Path(__file__).parent
required={'live-login.spec.ts','live-ehr.spec.ts','live-search.spec.ts','live-selection.spec.ts','live-dashboard.spec.ts','dashboard-performance.spec.ts','workflows-live.spec.ts','commit-live.spec.ts','ambulatory-live-host.spec.ts','surgery-live-realism.spec.ts'}
report_file=root/'desktop-playwright.json'
if report_file.exists():
 report=json.loads(report_file.read_text())
else:
 text=(root/'desktop.log').read_text()
 match=re.search(r'(?m)^\{\s*"config"\s*:',text)
 assert match,'Missing JSON Playwright report'
 report,_=json.JSONDecoder().raw_decode(text[match.start():])
assert not report.get('errors',[]),report.get('errors')
assert report['stats']['unexpected']==0 and report['stats']['flaky']==0,report['stats']
found={name:[] for name in required}
optional_skipped=[]
def visit(suite,parent_file=''):
 file=suite.get('file',parent_file)
 for spec in suite.get('specs',[]):
  name=Path(spec.get('file',file)).name
  for test in spec['tests']:
   results=test['results'];assert results,(name,spec['title'])
   row={'file':name,'title':spec['title'],'status':results[-1]['status']}
   if name in found:found[name].append(row)
   elif row['status']=='skipped':optional_skipped.append(row)
 for child in suite.get('suites',[]):visit(child,file)
for suite in report['suites']:visit(suite)
assert all(found.values()),[name for name,rows in found.items() if not rows]
assert all(row['status']=='passed' for rows in found.values() for row in rows),found
summary={'stats':report['stats'],'requiredPassed':sum(map(len,found.values())),'requiredFiles':{name:len(rows) for name,rows in found.items()},'optionalSkipped':optional_skipped}
(root/'desktop-required.json').write_text(json.dumps(summary,indent=2)+'\n')
print(json.dumps(summary))

